package com.moodcanvas.dao;
import com.moodcanvas.model.User;import com.moodcanvas.util.DBConnection;import java.sql.*;
public class UserDAO {public User getUserByEmail(String email)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE email=?")){p.setString(1,email);try(ResultSet r=p.executeQuery()){return r.next()?new User(r.getInt("userID"),r.getString("name"),r.getString("email"),r.getString("passwordHash"),r.getString("role"),r.getString("theme")):null;}}}public boolean emailExists(String e)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM users WHERE email=?")){p.setString(1,e);try(ResultSet r=p.executeQuery()){return r.next();}}}public void createUser(String n,String e,String h)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,passwordHash) VALUES(?,?,?)")){p.setString(1,n);p.setString(2,e);p.setString(3,h);p.executeUpdate();}}public void updateTheme(int id,String t)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE users SET theme=? WHERE userID=?")){p.setString(1,t);p.setInt(2,id);p.executeUpdate();}}public int count()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM users");ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}public java.util.List<User> getAll()throws SQLException{java.util.List<User> list=new java.util.ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT userID,name,email,passwordHash,role,theme FROM users ORDER BY createdAt DESC");ResultSet r=p.executeQuery()){while(r.next())list.add(new User(r.getInt("userID"),r.getString("name"),r.getString("email"),r.getString("passwordHash"),r.getString("role"),r.getString("theme")));}return list;}}
